// Generate two fuzzed int values
int a = *FUZZ_PARAM(int);
int b = *FUZZ_PARAM(int);

// Enforce no signed overflow: compute in a wider type and ensure it round-trips to int
long long sum_ll = (long long)a + (long long)b;
if (sum_ll != (long long)(int)sum_ll) {
    // If the sum cannot be represented as int, the API contract forbids this call
    FUZZ_BAIL();
}

// Call the target function
int result = tmux_public_sum(a, b);

// Property check: result must equal a + b when representable in int
FUZZ_ASSERT(result == (int)sum_ll, "tmux_public_sum must return exact a+b without overflow");

